import java.nio.file.*;import java.util.*;import java.util.jar.*;
import org.objectweb.asm.*;import org.objectweb.asm.tree.*;
public final class PatchStone implements Opcodes {
 static ClassNode read(JarFile jar,String name)throws Exception{var n=new ClassNode();new ClassReader(jar.getInputStream(jar.getJarEntry(name+".class"))).accept(n,0);return n;}
 static MethodNode method(ClassNode n,String name,String desc){return n.methods.stream().filter(m->m.name.equals(name)&&m.desc.equals(desc)).findFirst().orElseThrow();}
 static void clear(MethodNode m){m.instructions.clear();m.tryCatchBlocks.clear();if(m.localVariables!=null)m.localVariables.clear();m.visibleLocalVariableAnnotations=null;m.invisibleLocalVariableAnnotations=null;}
 static void save(ClassNode n,Path out)throws Exception{var w=new ClassWriter(ClassWriter.COMPUTE_MAXS);n.accept(w);var p=out.resolve(n.name+".class");Files.createDirectories(p.getParent());Files.write(p,w.toByteArray());}
 static final String RL="Lnet/minecraft/resources/ResourceLocation;",STACK="Lnet/minecraft/world/item/ItemStack;",CREATIVE="cn/fusionarsenal/CreativeStone",REG="cn/fusionarsenal/api/UltimateStoneRegistry";
 public static void main(String[]a)throws Exception{try(var jar=new JarFile(a[0])){Path out=Path.of(a[1]);
  var n=read(jar,"cn/judgfire/EnergyAttributes");var m=method(n,"amount","("+STACK+"Z)D");clear(m);
  m.instructions.add(new VarInsnNode(ALOAD,0));m.instructions.add(new VarInsnNode(ILOAD,1));m.instructions.add(new MethodInsnNode(INVOKESTATIC,"cn/fusionarsenal/EyeAccessoryEnergy","resistanceOrPenetration","("+STACK+"Z)D",false));
  m.instructions.add(new VarInsnNode(ALOAD,0));m.instructions.add(new VarInsnNode(ILOAD,1));m.instructions.add(new MethodInsnNode(INVOKESTATIC,CREATIVE,"amount","("+STACK+"Z)D",false));m.instructions.add(new InsnNode(DADD));m.instructions.add(new InsnNode(DRETURN));
  m=new MethodNode(ACC_PUBLIC|ACC_STATIC,"strength","(Lnet/minecraft/world/entity/LivingEntity;)D",null,null);m.instructions.add(new VarInsnNode(ALOAD,0));m.instructions.add(new MethodInsnNode(INVOKESTATIC,"cn/judgfire/StrengthAttributes","value",m.desc,false));m.instructions.add(new InsnNode(DRETURN));n.methods.add(m);save(n,out);
  n=read(jar,"cn/fusionarsenal/EyeAccessoryEnergy");m=method(n,"strength","("+STACK+")D");int added=0;for(var ins:m.instructions.toArray())if(ins.getOpcode()==DRETURN){var x=new InsnList();x.add(new VarInsnNode(ALOAD,0));x.add(new MethodInsnNode(INVOKESTATIC,CREATIVE,"strength","("+STACK+")D",false));x.add(new InsnNode(DADD));m.instructions.insertBefore(ins,x);added++;}if(added!=1)throw new AssertionError(added);save(n,out);
  n=read(jar,"cn/fusionarsenal/EnergyUpgradeRules");m=method(n,"amount","("+RL+RL+"Z)D");clear(m);m.instructions.add(new VarInsnNode(ALOAD,0));m.instructions.add(new VarInsnNode(ALOAD,1));m.instructions.add(new VarInsnNode(ILOAD,2));m.instructions.add(new MethodInsnNode(INVOKESTATIC,CREATIVE,"amount",m.desc,false));m.instructions.add(new InsnNode(DRETURN));save(n,out);
  n=read(jar,"cn/fusionarsenal/GeneratedUpgradeCatalog");m=method(n,"definitions","()Ljava/util/List;");clear(m);m.instructions.add(new MethodInsnNode(INVOKESTATIC,"java/util/List","of","()Ljava/util/List;",true));m.instructions.add(new InsnNode(ARETURN));save(n,out);
  n=read(jar,"cn/judgfire/CombatConfig");m=method(n,"attachmentEnergy","("+RL+"Z)D");clear(m);m.instructions.add(new InsnNode(DCONST_0));m.instructions.add(new InsnNode(DRETURN));save(n,out);
  n=read(jar,"cn/punishmenteye/UltimateRequirement");m=method(n,"matches","("+RL+RL+")Z");clear(m);m.instructions.add(new VarInsnNode(ALOAD,0));m.instructions.add(new VarInsnNode(ALOAD,1));m.instructions.add(new FieldInsnNode(GETSTATIC,n.name,"STONE",RL));m.instructions.add(new MethodInsnNode(INVOKESTATIC,REG,"matches","("+RL+RL+RL+")Z",false));m.instructions.add(new InsnNode(IRETURN));
  m=method(n,"installed","("+STACK+")Z");clear(m);m.instructions.add(new VarInsnNode(ALOAD,0));m.instructions.add(new FieldInsnNode(GETSTATIC,n.name,"STONE",RL));m.instructions.add(new MethodInsnNode(INVOKESTATIC,REG,"installed","("+STACK+RL+")Z",false));m.instructions.add(new InsnNode(IRETURN));save(n,out);
  n=read(jar,"cn/judgfire/CrownRangeBonus");m=method(n,"supports","("+RL+")Z");clear(m);m.instructions.add(new FieldInsnNode(GETSTATIC,"cn/judgfire/JudgmentFlame","GUN",RL));m.instructions.add(new VarInsnNode(ALOAD,0));m.instructions.add(new FieldInsnNode(GETSTATIC,"cn/judgfire/LaserAttachments","ULTIMATE",RL));m.instructions.add(new MethodInsnNode(INVOKESTATIC,REG,"matches","("+RL+RL+RL+")Z",false));m.instructions.add(new InsnNode(IRETURN));
  m=method(n,"apply","("+STACK+"DF)F");clear(m);m.instructions.add(new VarInsnNode(ALOAD,0));m.instructions.add(new VarInsnNode(DLOAD,1));m.instructions.add(new VarInsnNode(FLOAD,3));m.instructions.add(new MethodInsnNode(INVOKESTATIC,"cn/judgfire/UltimateCrownSupport","apply",m.desc,false));m.instructions.add(new InsnNode(FRETURN));save(n,out);
  n=read(jar,"cn/punishmenteye/KingHeartRules");m=method(n,"allDamage","(FZ)F");clear(m);m.instructions.add(new VarInsnNode(FLOAD,0));m.instructions.add(new InsnNode(FRETURN));save(n,out);
  n=read(jar,"cn/punishmenteye/UltimateRules");m=method(n,"allDamage","(FZZ)F");clear(m);m.instructions.add(new VarInsnNode(FLOAD,0));m.instructions.add(new InsnNode(FRETURN));save(n,out);
  System.out.println("Patched nine classes; added strength total getter; all other method bodies retained");
 }}
}
